package com.ledgerline.service;

import com.ledgerline.dto.*;
import com.ledgerline.entity.*;
import com.ledgerline.exception.BusinessException;
import com.ledgerline.repository.*;
import lombok.RequiredArgsConstructor;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;
import java.time.LocalDateTime;
import java.util.*;

@Service @RequiredArgsConstructor
public class InventoryService {
 private final JdbcTemplate jdbc; private final ProductRepository products; private final CategoryRepository categories; private final SupplierRepository suppliers; private final WarehouseRepository warehouses; private final LocationRepository locations; private final PurchaseOrderRepository purchaseOrders; private final StockMovementRepository movements; private final UserRepository users;
 public Map<String,Object> dashboard(){Map<String,Object> m=new LinkedHashMap<>();m.put("products",jdbc.queryForObject("SELECT COUNT(*) FROM product WHERE active=1",Long.class));m.put("stock",jdbc.queryForObject("SELECT COALESCE(SUM(quantity),0) FROM stock_balance",BigDecimal.class));m.put("value",jdbc.queryForObject("SELECT COALESCE(SUM(b.quantity*p.cost),0) FROM stock_balance b JOIN product p ON p.id=b.product_id",BigDecimal.class));m.put("low",lowStock(null,null).size());return m;}
 public List<Product> products(String q){return q==null||q.isBlank()?products.findAll():products.findByActiveTrueAndNameContainingIgnoreCaseOrActiveTrueAndSkuContainingIgnoreCase(q,q);}
 @Transactional public Product create(ProductRequest r){Product p=new Product();p.setSku(r.sku());p.setName(r.name());p.setCategory(categories.findById(r.categoryId()).orElseThrow(()->new BusinessException("Category not found")));p.setSupplier(suppliers.findById(r.supplierId()).orElseThrow(()->new BusinessException("Supplier not found")));p.setReorderLevel(r.reorderLevel());p.setCost(r.cost());p.setPrice(r.price());return products.save(p);}
 public List<Map<String,Object>> ledger(){return jdbc.queryForList("SELECT m.reference_code reference,p.sku,p.name product,w.name warehouse,m.quantity,m.movement_type type,m.created_at FROM stock_movement m JOIN product p ON p.id=m.product_id JOIN warehouse w ON w.id=m.warehouse_id ORDER BY m.created_at DESC LIMIT 500");}
 public List<LowStockItem> lowStock(String search, Long warehouseId){StringBuilder sql=new StringBuilder("SELECT p.sku,p.name product_name,w.name warehouse_name,COALESCE(SUM(b.quantity),0) quantity,p.reorder_level FROM product p JOIN warehouse w ON w.active=1 LEFT JOIN stock_balance b ON b.product_id=p.id AND b.warehouse_id=w.id WHERE p.active=1 ");List<Object> args=new ArrayList<>();if(search!=null&&!search.isBlank()){sql.append("AND (p.name LIKE ? OR p.sku LIKE ? OR w.name LIKE ?) ");String term="%"+search.trim()+"%";args.add(term);args.add(term);args.add(term);}if(warehouseId!=null){sql.append("AND w.id=? ");args.add(warehouseId);}sql.append("GROUP BY p.id,p.sku,p.name,w.id,w.name,p.reorder_level HAVING COALESCE(SUM(b.quantity),0)<=p.reorder_level ORDER BY p.reorder_level-COALESCE(SUM(b.quantity),0) DESC,p.name,w.name");return jdbc.query(sql.toString(),(rs,n)->{BigDecimal quantity=rs.getBigDecimal("quantity"),reorder=rs.getBigDecimal("reorder_level");return new LowStockItem(rs.getString("sku"),rs.getString("product_name"),rs.getString("warehouse_name"),quantity,reorder,LowStockRules.shortage(quantity,reorder));},args.toArray());}
 @Transactional public void stock(StockRequest r){BigDecimal amount=(r.type().equals("ISSUE")||r.type().equals("DAMAGE")||r.type().equals("SALE"))?r.quantity().negate():r.quantity();adjust(r.productId(),r.warehouseId(),r.locationId(),amount,r.type(),r.reference(),r.reason());}
 @Transactional public void transfer(TransferRequest r){adjust(r.productId(),r.fromWarehouse(),r.fromLocation(),r.quantity().negate(),"TRANSFER_OUT",r.reference(),"Warehouse transfer");adjust(r.productId(),r.toWarehouse(),r.toLocation(),r.quantity(),"TRANSFER_IN",r.reference(),"Warehouse transfer");}
 @Transactional public PurchaseOrder createPurchase(PurchaseRequest r){PurchaseOrder p=new PurchaseOrder();p.setOrderNumber(r.orderNumber());p.setSupplier(suppliers.findById(r.supplierId()).orElseThrow());p.setWarehouse(warehouses.findById(r.warehouseId()).orElseThrow());p.setStatus("DRAFT");p.setOrderedAt(LocalDateTime.now());PurchaseOrder saved=purchaseOrders.save(p);jdbc.update("INSERT INTO purchase_order_item(purchase_order_id,product_id,ordered_qty,cost) VALUES(?,?,?,?)",saved.getId(),r.productId(),r.quantity(),r.cost());return saved;}
 @Transactional public void approve(Long id){purchaseOrders.findById(id).ifPresentOrElse(p->{if(!p.getStatus().equals("DRAFT"))throw new BusinessException("Only drafts can be approved");p.setStatus("APPROVED");purchaseOrders.save(p);},()->{throw new BusinessException("Purchase order not found");});}
 @Transactional public void receive(Long id,Long product,Long warehouse,Long location,BigDecimal quantity){Map<String,Object> i=jdbc.queryForMap("SELECT po.status,poi.ordered_qty-poi.received_qty remaining FROM purchase_order po JOIN purchase_order_item poi ON poi.purchase_order_id=po.id WHERE po.id=? AND poi.product_id=? FOR UPDATE",id,product);if(!"APPROVED".equals(i.get("status"))&&!"PARTIALLY_RECEIVED".equals(i.get("status")))throw new BusinessException("Only approved purchase orders can be received");BigDecimal remaining=(BigDecimal)i.get("remaining");if(quantity.signum()<=0||quantity.compareTo(remaining)>0)throw new BusinessException("Receipt exceeds outstanding quantity");if(jdbc.queryForObject("SELECT COUNT(*) FROM location WHERE id=? AND warehouse_id=?",Integer.class,location,warehouse)==0)throw new BusinessException("Location does not belong to warehouse");adjust(product,warehouse,location,quantity,"RECEIPT","PO-"+id,"Goods received");jdbc.update("UPDATE purchase_order_item SET received_qty=received_qty+? WHERE purchase_order_id=? AND product_id=?",quantity,id,product);jdbc.update("UPDATE purchase_order SET status=CASE WHEN (SELECT SUM(ordered_qty-received_qty) FROM purchase_order_item WHERE purchase_order_id=?)=0 THEN 'RECEIVED' ELSE 'PARTIALLY_RECEIVED' END WHERE id=?",id,id);}
 public String csv(){StringBuilder b=new StringBuilder("Reference,SKU,Product,Warehouse,Quantity,Type,Created\n");for(Map<String,Object> row:ledger()){for(Object v:row.values())b.append('"').append(String.valueOf(v).replace("\"","\"\"")).append("\",");b.setLength(b.length()-1);b.append('\n');}return b.toString();}
 public List<Category> categories(){return categories.findAll();}public List<Supplier> suppliers(){return suppliers.findByActiveTrueOrderByName();}public List<Warehouse> warehouses(){return warehouses.findByActiveTrueOrderByName();}public List<Location> locations(){return locations.findAllByOrderByCode();}public List<PurchaseOrder> purchases(){return purchaseOrders.findAllByOrderByOrderedAtDesc();}public List<Map<String,Object>> purchaseRows(){return jdbc.queryForList("SELECT po.id,po.order_number orderNumber,s.name supplier,w.name warehouse,w.id warehouseId,po.status,po.ordered_at orderedAt,poi.product_id productId,p.name product,p.sku,poi.ordered_qty orderedQty,poi.received_qty receivedQty FROM purchase_order po JOIN supplier s ON s.id=po.supplier_id JOIN warehouse w ON w.id=po.warehouse_id JOIN purchase_order_item poi ON poi.purchase_order_id=po.id JOIN product p ON p.id=poi.product_id ORDER BY po.ordered_at DESC,poi.id");}
 private void adjust(Long product,Long warehouse,Long location,BigDecimal amount,String type,String ref,String reason){if(reason==null||reason.isBlank())throw new BusinessException("Reason is required");BigDecimal current=jdbc.query("SELECT quantity FROM stock_balance WHERE product_id=? AND warehouse_id=? AND location_id=? FOR UPDATE",(rs,n)->rs.next()?rs.getBigDecimal(1):BigDecimal.ZERO,product,warehouse,location).stream().findFirst().orElse(BigDecimal.ZERO);if(current.add(amount).signum()<0)throw new BusinessException("Insufficient stock");jdbc.update("INSERT INTO stock_balance(product_id,warehouse_id,location_id,quantity) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE quantity=quantity+VALUES(quantity)",product,warehouse,location,amount);jdbc.update("INSERT INTO stock_movement(product_id,warehouse_id,location_id,quantity,movement_type,reference_code,reason,created_by) VALUES(?,?,?,?,?,?,?,?)",product,warehouse,location,amount,type,ref,reason,currentUser());}
 private Long currentUser(){String email=SecurityContextHolder.getContext().getAuthentication().getName();return users.findByEmailAndActiveTrue(email).map(User::getId).orElseThrow();}
}
